    print("SUCCESS! Elliptic curve computed.")
    print("="*_sage_const_80 )
    print(E)
    print("="*_sage_const_80 )
    print()

    # Get the Weierstrass coefficients [a1, a2, a3, a4, a6]
    ainvs = E.ainvs()

