    # For standard form y^2 = x^3 + a4*x + a6, we need a1=a2=a3=0
    # Let's see what we got
    a1_poly = ainvs[_sage_const_0 ]
    a2_poly = ainvs[_sage_const_1 ]
    a3_poly = ainvs[_sage_const_2 ]
    a4_poly = ainvs[_sage_const_3 ]
    a6_poly = ainvs[_sage_const_4 ]

    print("="*_sage_const_80 )
    print("EXTRACTING POLYNOMIAL COEFFICIENTS FOR JULIA")
    print("="*_sage_const_80 )
