    # Get numerator and denominator for a4
    if hasattr(a4_poly, 'numerator'):
        a4_num = a4_poly.numerator()
        a4_den = a4_poly.denominator()
    else:
        a4_num = a4_poly
        a4_den = _sage_const_1 

    # Get numerator and denominator for a6
    if hasattr(a6_poly, 'numerator'):
        a6_num = a6_poly.numerator()
        a6_den = a6_poly.denominator()
